shellCommands.command:
cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import dynamicImport from 'vite-plugin-dynamic-import';

export default defineConfig({
  plugins: [
    react(),
    // Required by @gravity-ui/page-constructor for its dynamic block imports under Vite.
    dynamicImport({
      filter: (id) => id.includes('/node_modules/@gravity-ui/page-constructor'),
    }),
  ],
});
EOF
cat > src/App.css <<'EOF'
/* page-constructor grid does not ship a box-sizing reset; without it the
   container padding overflows the viewport horizontally. */
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}
EOF
